/* Nearest-corner maths + search. Straight-line distance only (no routing,
   no network): walking time pads it ×1.3 for real paths at ~4.8 km/h. */
const WALK_M_PER_MIN = 80;
const WALK_DETOUR = 1.3;
const SG_CORNER_LIST = SG_CORNERS.map((r) => ({ id: r[0], name: r[1], desc: r[2], lat: r[3], lng: r[4], area: r[5], pcn: r[6] }));
const SG_CORNER_BY_ID = Object.fromEntries(SG_CORNER_LIST.map((c) => [c.id, c]));
function distM(aLat, aLng, bLat, bLng) {
  const R = 6371000, rad = Math.PI / 180;
  const dLat = (bLat - aLat) * rad, dLng = (bLng - aLng) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(aLat * rad) * Math.cos(bLat * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}
const fmtDist = (m) => (m < 1000 ? `${Math.max(10, Math.round(m / 10) * 10)} m` : `${(m / 1000).toFixed(m < 10000 ? 1 : 0)} km`);
const walkMin = (m) => Math.max(1, Math.round((m * WALK_DETOUR) / WALK_M_PER_MIN));
const fmtWalk = (m) => { const w = walkMin(m); return w < 90 ? `~${w} min walk` : `~${Math.round(w / 60)} h walk`; };
function nearestCorners(lat, lng, n = 5) {
  return SG_CORNER_LIST.map((c) => ({ ...c, dist: distM(lat, lng, c.lat, c.lng) })).sort((a, b) => a.dist - b.dist).slice(0, n);
}
function searchCorners(q, n = 25) {
  const toks = q.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  if (!toks.length) return [];
  return SG_CORNER_LIST.filter((c) => {
    const hay = `${c.name} ${c.area} ${c.pcn} ${c.desc}`.toLowerCase();
    return toks.every((tk) => hay.includes(tk));
  }).slice(0, n);
}
const dirLinks = (c) => ({
  apple: `https://maps.apple.com/?daddr=${c.lat},${c.lng}&dirflg=w&q=${encodeURIComponent(c.name)}`,
  google: `https://www.google.com/maps/dir/?api=1&destination=${c.lat},${c.lng}&travelmode=walking`,
});
const fmtDay = (iso) => new Date(iso).toLocaleDateString("en-SG", { day: "numeric", month: "short", year: "numeric" });

